/* MiLibroPDF Web — biblioteca local-first. Los libros permanecen en el navegador. */
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>Array.from(root.querySelectorAll(s));
const ico = (name)=>'<svg aria-hidden="true"><use href="#i-'+name+'"></use></svg>';
const esc = (s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate = (x)=>x?new Date(x).toLocaleDateString('es-AR',{day:'numeric',month:'short',year:'numeric'}):'—';
const prettyTime = (s)=>s<60?Math.round(s)+' s':s<3600?Math.round(s/60)+' min':Math.floor(s/3600)+' h '+Math.round(s%3600/60)+' min';
const dateKey = (date=new Date())=>{const d=new Date(date);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const uid = ()=>crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2);
const defaultSettings={readerTheme:'sepia',fontSize:19,lineHeight:1.7,voiceSpeed:1,voiceName:'',sleep:0,keepAwake:false,smartTimeout:0,grid:true,sort:'recent',epubFlow:'paginated',goalMinutes:20};
const sampleChapters=[
 {title:'I. El pequeño ritual',text:'Los libros tienen una manera silenciosa de acompañarnos. A veces basta con abrir una página para que el ruido cotidiano quede un poco más lejos.\n\nLeer no es una carrera. No hay medalla por terminar primero ni obligación de recordar cada frase. Es, sobre todo, una conversación: alguien dejó sus ideas aquí y nosotros decidimos escucharlas.\n\nProbá leer unos minutos sin apuro. Volvé sobre una línea si te llama la atención. Guardá las palabras que quieras volver a encontrar. La lectura puede ser un lugar al que regresamos, no una tarea pendiente.\n\nMiLibroPDF nació para cuidar justamente eso: la relación íntima entre una persona y sus libros.'},
 {title:'II. Las ideas que quedan',text:'Algunos párrafos se nos escapan casi enseguida. Otros permanecen durante años. Nadie sabe con exactitud cuál de ellos se convertirá en una idea importante.\n\nPor eso sirve subrayar, tomar una nota o guardar un fragmento. No para estudiar cada palabra, sino para poder regresar a lo que una vez nos hizo pensar.\n\nUn libro leído nunca es exactamente el mismo para dos personas. Cambia con nuestras preguntas, con los días, con la experiencia que llevamos a sus páginas. Y también cambia cuando lo volvemos a abrir.'},
 {title:'III. Seguir leyendo',text:'Una biblioteca personal no se mide solo por la cantidad de títulos que reúne, sino por la cantidad de caminos que abre.\n\nHay libros que abandonamos y retomamos meses después. Hay textos técnicos que consultamos una y otra vez. Y hay historias que preferimos no terminar demasiado rápido.\n\nNo importa el ritmo: siempre hay una próxima página.\n\nImportá tus propios archivos PDF o EPUB para llevar esta experiencia a tus lecturas reales.'}
];
const sampleBook={id:'demo-bienvenida',title:'El placer de leer',author:'MiLibroPDF · Guía de bienvenida',format:'DEMO',fileName:'Libro de muestra',size:0,addedAt:Date.now()-86400000,lastOpened:0,progress:0,position:0,page:1,totalPages:3,status:'unread',favorite:false,archived:false,time:0,sample:true};
let db=null;
function openDB(){return new Promise((res,rej)=>{const req=indexedDB.open('milibropdf-web',1);req.onupgradeneeded=()=>{const d=req.result;for(const name of ['books','files','annotations','sessions','prefs'])if(!d.objectStoreNames.contains(name))d.createObjectStore(name,{keyPath:'id'})};req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)})}
function idbStore(table,mode='readonly'){return db.transaction(table,mode).objectStore(table)}
function getAll(table){return new Promise((res,rej)=>{const r=idbStore(table).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function getOne(table,id){return new Promise((res,rej)=>{const r=idbStore(table).get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function putOne(table,obj){return new Promise((res,rej)=>{const r=idbStore(table,'readwrite').put(obj);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
function deleteOne(table,id){return new Promise((res,rej)=>{const r=idbStore(table,'readwrite').delete(id);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
const state={view:'home',books:[],annotations:[],sessions:[],settings:{...defaultSettings},filter:'all',type:'all',studyFilter:'all',studyQuery:'',query:'',collectionFilter:'all',tagFilter:'all',collections:[],palette:false,paletteQuery:'',detail:null,reader:null,readerSide:'',page:1,pdf:null,pdfPage:null,pdfScale:1,pdfRotation:0,epub:null,rendition:null,demoPage:0,selectedText:'',selectedPos:null,speaking:false,paused:false,phrases:[],phraseIndex:0,sessionStart:0,sessionPage:0,sleepTimeout:null,wakeLock:null,ttsTimer:null};
const bookBy=(id)=>state.books.find(x=>x.id===id);
const annotationsFor=(id)=>state.annotations.filter(x=>x.bookId===id);
const readBooks=()=>state.books.filter(x=>x.lastOpened&&x.progress<100).sort((a,b)=>b.lastOpened-a.lastOpened);
const coverVariant=(b)=>'abcdef'.charAt(Math.abs(Array.from(b.id).reduce((h,c)=>h*31+c.charCodeAt(0)|0,0))%6);
function cover(b,cls=''){return '<div class="cover '+coverVariant(b)+' '+cls+'"><span class="cover-small">'+esc(b.format==='DEMO'?'EDICIÓN DE BIENVENIDA':b.format+' · MiLibroPDF')+'</span><div class="cover-title">'+esc(b.title)+'</div><span class="cover-author">'+esc(b.author||'Autor desconocido')+'</span><span class="cover-mark">✦</span></div>'}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.add('hidden'),3900)}
function getDailySeconds(offset=0){const wanted=dateKey(Date.now()-offset*86400000);return state.sessions.filter(s=>dateKey(s.start)===wanted).reduce((n,s)=>n+s.duration,0)}
function renderNavButton(view,label,icon){return '<button data-nav="'+view+'" class="navlink '+(state.view===view?'active':'')+'">'+ico(icon)+'<span>'+label+'</span></button>'}
function renderMobileButton(view,label,icon){return '<button data-nav="'+view+'" class="'+(state.view===view?'active':'')+'">'+ico(icon)+'<span>'+label+'</span></button>'}
function render(){
  const pages={home:'Resumen',library:'Biblioteca',collections:'Colecciones',study:'Mis apuntes',stats:'Estadísticas',settings:'Ajustes'};
  const current=Math.round(getDailySeconds()/60),target=Number(state.settings.goalMinutes)||20;
  const app=$('#app');
  app.innerHTML=`<div class="shell"><aside class="sidebar">
    <div class="brand"><div class="brandmark">${ico('book')}</div><div><div class="brandname">MiLibro<span>PDF</span></div><div class="brandsub">Tu biblioteca personal</div></div></div>
    <div class="nav-label">TU ESTANTERÍA</div><nav class="navlinks">
      ${renderNavButton('home','Mi espacio','home')}${renderNavButton('library','Mi biblioteca','library')}${renderNavButton('collections','Colecciones','grid')}${renderNavButton('study','Notas y fragmentos','quote')}
      <div class="nav-divider"></div>${renderNavButton('stats','Estadísticas','stats')}${renderNavButton('settings','Preferencias','settings')}
    </nav><div class="side-bottom"><div class="side-goal"><span class="side-goal-top">OBJETIVO DE HOY <span>✦</span></span><strong>${current} <small>/ ${target} min</small></strong><div class="goal-track"><div style="width:${Math.min(100,current/target*100)}%"></div></div><p>${current>=target?'¡Objetivo cumplido! Seguí así.':'Unos minutos más y seguís creciendo.'}</p><button data-nav="stats">Ver mi actividad ${ico('arrow')}</button></div><div class="side-footer">MiLibroPDF <span>•</span> v3.0<br>Privado y guardado en este navegador</div></div>
  </aside><div class="content-shell"><header class="topbar"><div class="top-left"><span class="top-eyebrow">HECHO PARA LEER</span><div class="crumb">${pages[state.view]||'MiLibroPDF'}<span class="top-crumb-dot">/</span><b>Tu espacio</b></div></div>
    <div class="top-actions"><button class="search-trigger" data-action="palette" title="Búsqueda rápida">${ico('search')}<span>Buscar en mi biblioteca...</span><kbd>Ctrl K</kbd></button><button class="primary-btn top-import" data-action="import">${ico('plus')}<span class="add-label">Nuevo libro</span></button><span class="avatar" title="Biblioteca privada">M</span></div>
  </header><main class="page" id="page">${state.view==='home'?homePage():state.view==='library'?libraryPage():state.view==='collections'?collectionsPage():state.view==='study'?studyPage():state.view==='stats'?statsPage():settingsPage()}</main></div>
  <nav class="mobile-nav">${renderMobileButton('home','Inicio','home')}${renderMobileButton('library','Biblioteca','library')}${renderMobileButton('collections','Colecciones','grid')}${renderMobileButton('study','Apuntes','quote')}${renderMobileButton('stats','Actividad','stats')}${renderMobileButton('settings','Ajustes','settings')}</nav></div>
  ${state.detail?detailModal(bookBy(state.detail)):''}${state.reader?readerMarkup():''}${state.palette?paletteMarkup():''}`;
  document.body.classList.toggle('reading',!!state.reader);
  if(state.palette){const field=$('#palette-search');if(field)field.focus()}
}
function bookCard(b){return `<article class="book-card" role="button" tabindex="0" data-book="${esc(b.id)}">${cover(b)}<div class="card-main"><div class="card-row"><h3 title="${esc(b.title)}">${esc(b.title)}</h3></div><p>${esc(b.author||'Autor desconocido')}</p><div class="card-row"><span class="type-badge ${b.format.toLowerCase()}">${esc(b.format)}</span>${b.readLater?'<span title="Leer después" class="queue-badge">En lista</span>':''}${b.favorite?'<span class="favorite-star">♥</span>':''}</div><div class="progress-row"><div class="progress-track"><div class="progress-fill" style="width:${Math.round(b.progress||0)}%"></div></div><span>${Math.round(b.progress||0)}%</span></div></div></article>`}
function filterBooks(){let list=state.books.filter(b=>!b.archived);const q=state.query.trim().toLocaleLowerCase('es');if(q)list=list.filter(b=>(b.title+' '+b.author+' '+b.fileName+' '+(b.tags||[]).join(' ')).toLocaleLowerCase('es').includes(q));if(state.filter==='reading')list=list.filter(b=>b.progress>0&&b.progress<100);if(state.filter==='unread')list=list.filter(b=>b.progress===0);if(state.filter==='finished')list=list.filter(b=>b.progress>=100);if(state.filter==='favorites')list=list.filter(b=>b.favorite);if(state.filter==='queue')list=list.filter(b=>b.readLater);if(state.collectionFilter!=='all')list=list.filter(b=>(b.collections||[]).includes(state.collectionFilter));if(state.tagFilter!=='all')list=list.filter(b=>(b.tags||[]).includes(state.tagFilter));if(state.type!=='all')list=list.filter(b=>b.format.toLowerCase()===state.type);const sort=state.settings.sort;if(sort==='title')list.sort((a,b)=>a.title.localeCompare(b.title));else if(sort==='author')list.sort((a,b)=>(a.author||'').localeCompare(b.author||''));else if(sort==='progress')list.sort((a,b)=>b.progress-a.progress);else if(sort==='added')list.sort((a,b)=>b.addedAt-a.addedAt);else list.sort((a,b)=>(b.lastOpened||b.addedAt)-(a.lastOpened||a.addedAt));return list}
function homePage(){
 const current=readBooks()[0]||state.books.find(b=>b.sample)||state.books[0];
 const recent=[...state.books].filter(b=>!b.archived).sort((a,b)=>(b.lastOpened||b.addedAt)-(a.lastOpened||a.addedAt)).slice(0,5);
 const minutes=Math.round(getDailySeconds()/60),goal=Math.max(1,Number(state.settings.goalMinutes)||20),streak=readingStreak();
 const completed=state.books.filter(b=>b.progress>=100).length,active=state.books.filter(b=>b.progress>0&&b.progress<100).length;
 const queue=state.books.filter(b=>b.readLater&&!b.archived).slice(0,3);
 const upcoming=state.books.filter(b=>b.targetDate&&b.progress<100&&!b.archived).sort((a,b)=>a.targetDate.localeCompare(b.targetDate)).slice(0,2);
 return `<div class="page-head modern-heading"><div><p class="eyebrow">BIENVENIDO A TU RINCÓN DE LECTURA <span>✧</span></p><h1>Un lugar para <em>perderse entre páginas</em><span class="period">.</span></h1><p class="sub">Tus libros, tus ideas y ese momento que es solo tuyo.</p></div><span class="date-kicker">${new Date().toLocaleDateString('es-AR',{weekday:'long',day:'numeric',month:'long'})}</span></div>
 <div class="dashboard-top"><section class="hero"><div class="hero-orb"></div><div class="hero-copy"><div class="hero-kicker"><span></span>${current&&current.lastOpened?'DONDE LO DEJASTE':'TU PRÓXIMA LECTURA TE ESPERA'}</div><h2>${current&&current.lastOpened?'Siempre hay una página más.':'Cada libro abre un mundo nuevo.'}</h2><p>${current&&current.lastOpened?'Retomá “'+esc(current.title)+'” justo donde lo dejaste.':'Creá tu biblioteca. Leé, escuchá y guardá las ideas que merecen quedarse.'}</p><button class="hero-btn" data-action="${current?'read':'import'}" ${current?'data-id="'+esc(current.id)+'"':''}>${ico(current?'book':'plus')} ${current?'Continuar leyendo':'Agregar mi primer libro'} ${ico('arrow')}</button></div><div class="hero-art"><div class="hero-book-shadow"></div>${cover(current||sampleBook,'hero-book')}</div></section>
 <section class="goal-widget"><div class="goal-widget-head"><span>RITMO DE LECTURA</span>${ico('spark')}</div><div class="goal-ring" style="--pct:${Math.min(100,minutes/goal*100)}"><div><strong>${minutes}</strong><small>de ${goal} min</small></div></div><h3>${minutes>=goal?'¡Meta cumplida!':'A tu propio ritmo.'}</h3><p>${minutes>=goal?'Hoy alcanzaste tu objetivo diario.':'No se trata de leer más. Se trata de disfrutar cada página.'}</p><button class="goal-config" data-action="change-goal">${ico('edit')} Personalizar meta</button></section></div>
 <div class="stats-strip"><div class="mini-stat"><div class="mini-icon">${ico('book')}</div><div><strong>${active}</strong><span>Lecturas en curso</span></div></div><div class="mini-stat"><div class="mini-icon">${ico('spark')}</div><div><strong>${streak} <small>días</small></strong><span>Racha de lectura</span></div></div><div class="mini-stat"><div class="mini-icon">${ico('check')}</div><div><strong>${completed}</strong><span>Libros terminados</span></div></div></div>
 <div class="dashboard-lower"><div class="dashboard-library"><div class="section-head"><div><p class="section-kicker">TU COLECCIÓN</p><h2>Tu biblioteca, a un clic.</h2><p>Una buena historia siempre merece un lugar.</p></div><button class="text-btn" data-nav="library">Explorar todos ${ico('arrow')}</button></div>${recent.length?'<div class="book-grid">'+recent.map(bookCard).join('')+'</div>':emptyBooks()}</div>
 <aside class="dashboard-aside"><div class="side-module"><div class="module-head"><span class="module-icon">${ico('clock')}</span><h3>Para leer después</h3></div>${queue.length?queue.map(b=>`<button class="queue-item" data-book="${esc(b.id)}"><span class="queue-dot"></span><span><b>${esc(b.title)}</b><small>${esc(b.author)}</small></span>${ico('chevron')}</button>`).join(''):'<p class="module-empty">Guardá libros para tu próxima lectura desde su ficha.</p>'}<button class="module-link" data-nav="library">Explorar la biblioteca ${ico('arrow')}</button></div><div class="side-module"><div class="module-head"><span class="module-icon amber">${ico('clock')}</span><h3>En el horizonte</h3></div>${upcoming.length?upcoming.map(b=>`<button class="queue-item" data-book="${esc(b.id)}"><span class="queue-dot amber"></span><span><b>${esc(b.title)}</b><small>Meta: ${esc(fmtDate(b.targetDate+'T12:00:00'))}</small></span>${ico('chevron')}</button>`).join(''):'<p class="module-empty">Asigná una fecha objetivo a un libro para organizar tus próximas lecturas.</p>'}</div></aside></div>
 <div class="footer-note">${ico('book')} Tu biblioteca es privada: los libros permanecen en este navegador. No hay sincronización entre dispositivos todavía.</div>`;
}
function emptyBooks(){return '<div class="empty"><div class="empty-icon">'+ico('book')+'</div><h3>Una estantería lista para vos</h3><p>Agregá un PDF o EPUB para comenzar a construir tu biblioteca personal.</p><button data-action="import" class="primary-btn">'+ico('plus')+'<span class="add-label">Agregar libro</span></button></div>'}
function libraryPage(){const list=filterBooks();const filters=[['all','Todos'],['reading','Leyendo'],['unread','Sin empezar'],['finished','Terminados'],['favorites','Favoritos'],['queue','Leer después']];const tags=allTags();return `<div class="page-head"><div><p class="eyebrow">TODOS TUS LIBROS</p><h1>Mi biblioteca<span class="period">.</span></h1><p class="sub">Todo lo que te gusta leer, organizado a tu manera.</p></div><button class="secondary-btn" data-action="import">${ico('upload')} Importar archivo</button></div>
 <div class="library-toolbar"><div class="filter-set">${filters.map(f=>`<button data-filter="${f[0]}" class="chip ${state.filter===f[0]?'active':''}">${f[1]}</button>`).join('')}</div><div class="toolbar-right"><label class="study-search library-search">${ico('search')}<input id="library-search" placeholder="Buscar por título, autor o etiqueta..." value="${esc(state.query)}" /></label><select class="select" id="collection-filter" aria-label="Colección"><option value="all">Todas las colecciones</option>${state.collections.map(c=>`<option value="${esc(c.id)}" ${state.collectionFilter===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select class="select" id="tag-filter" aria-label="Etiqueta"><option value="all">Todas las etiquetas</option>${tags.map(t=>`<option value="${esc(t)}" ${state.tagFilter===t?'selected':''}># ${esc(t)}</option>`).join('')}</select><select class="select" id="format-filter" aria-label="Formato"><option value="all" ${state.type==='all'?'selected':''}>Formatos</option><option value="pdf" ${state.type==='pdf'?'selected':''}>PDF</option><option value="epub" ${state.type==='epub'?'selected':''}>EPUB</option><option value="demo" ${state.type==='demo'?'selected':''}>Muestra</option></select><select class="select" id="sort-books" aria-label="Ordenar">${[['recent','Recientes'],['title','Por título'],['author','Por autor'],['progress','Por progreso'],['added','Fecha de carga']].map(x=>`<option value="${x[0]}" ${state.settings.sort===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><div class="view-switch"><button data-layout="grid" class="${state.settings.grid?'active':''}" title="Cuadrícula">${ico('grid')}</button><button data-layout="list" class="${!state.settings.grid?'active':''}" title="Lista">${ico('list')}</button></div></div></div>
 <div class="library-info"><span>${list.length} ${list.length===1?'libro':'libros'} en esta vista</span><button data-nav="collections">${ico('grid')} Gestionar colecciones</button></div>${list.length?`<div class="${state.settings.grid?'book-grid':'books-list'}">${list.map(bookCard).join('')}</div>`:emptyBooks()}<p class="footer-note">Importá archivos PDF y EPUB desde el botón o arrastrándolos a esta ventana.</p>`}
function studyPage(){let all=[...state.annotations].sort((a,b)=>b.createdAt-a.createdAt);if(state.studyFilter!=='all')all=all.filter(x=>x.type===state.studyFilter);const query=state.studyQuery.trim().toLocaleLowerCase('es');if(query)all=all.filter(a=>(a.text+' '+(a.selectedText||'')+' '+(bookBy(a.bookId)?.title||'')).toLocaleLowerCase('es').includes(query));const labels=[['all','Todos'],['highlight','Resaltados'],['fragment','Fragmentos'],['note','Notas']];return `<div class="page-head"><div><p class="eyebrow">TUS IDEAS, A MANO</p><h1>Apuntes e ideas<span class="period">.</span></h1><p class="sub">Tus notas, resaltados y frases favoritas, siempre cerca.</p></div><button class="secondary-btn" data-action="new-note">${ico('plus')} Nueva nota</button></div><div class="library-toolbar"><div class="filter-set">${labels.map(f=>`<button class="chip ${state.studyFilter===f[0]?'active':''}" data-study="${f[0]}">${f[1]}</button>`).join('')}</div><div class="toolbar-right"><label class="study-search">${ico('search')}<input id="study-search" placeholder="Buscar en mis apuntes..." value="${esc(state.studyQuery)}" /></label><button class="secondary-btn" data-action="export-markdown">${ico('download')} Exportar .md</button></div></div><p class="results-note">${all.length} ${all.length===1?'apunte encontrado':'apuntes encontrados'}</p>${all.length?`<div class="study-grid">${all.map(annotationCard).join('')}</div>`:`<div class="empty"><div class="empty-icon">${ico('quote')}</div><h3>${query?'No hay coincidencias':'Tus mejores ideas, reunidas'}</h3><p>${query?'Probá otra búsqueda o quitá los filtros.':'Seleccioná texto mientras leés para guardar fragmentos, notas o resaltados.'}</p></div>`}`}
function annotationCard(a){const b=bookBy(a.bookId);const desc=a.type==='highlight'?'Resaltado':a.type==='fragment'?'Fragmento':'Nota';return '<article class="annotation"><div class="annotation-meta"><span><b>'+desc+'</b> · '+esc(b?b.title:'Nota personal')+' · '+esc(a.locationLabel||'')+'</span><span>'+fmtDate(a.createdAt)+'</span></div><div class="annotation-quote '+a.type+'">'+esc(a.text)+'</div>'+(a.selectedText&&a.type==='note'?'<div class="small">Sobre: “'+esc(a.selectedText.slice(0,130))+'”</div>':'')+'<div class="annotation-actions">'+(b?'<button class="tiny-btn" data-action="jump" data-id="'+esc(a.id)+'">'+ico('book')+' Ir al libro</button>':'')+'<button class="tiny-btn" data-action="edit-annotation" data-id="'+esc(a.id)+'">'+ico('edit')+' Editar</button><button class="tiny-btn danger" data-action="delete-annotation" data-id="'+esc(a.id)+'">'+ico('trash')+' Eliminar</button></div></article>'}
function statsPage(){const minutes=state.sessions.reduce((n,s)=>n+s.duration,0)/60;const week=Array.from({length:7},(_,i)=>{const d=new Date(Date.now()-(6-i)*86400000);return {label:d.toLocaleDateString('es-AR',{weekday:'short'}).slice(0,3),minutes:Math.round(getDailySeconds(6-i)/60)}});const max=Math.max(...week.map(x=>x.minutes),5);const completed=state.books.filter(b=>b.progress>=100).length;const active=state.books.filter(b=>b.progress>0&&b.progress<100).length;const sessionCount=state.sessions.length;return '<div class="page-head"><div><p class="eyebrow">TU HISTORIA LECTORA</p><h1>Estadísticas</h1><p class="sub">Cada minuto de lectura suma algo valioso.</p></div></div><div class="goal-stats-banner">'+ico('spark')+' <span>Tu racha actual: <b>'+readingStreak()+' días</b></span><span>Objetivo diario: <b>'+Math.max(1,Number(state.settings.goalMinutes)||20)+' minutos</b></span><button data-action="change-goal">Cambiar meta</button></div><div class="stats-strip" style="margin-top:22px"><div class="mini-stat"><div class="mini-icon">'+ico('clock')+'</div><div><strong>'+Math.round(minutes)+'</strong><span>Minutos acumulados</span></div></div><div class="mini-stat"><div class="mini-icon">'+ico('book')+'</div><div><strong>'+active+'</strong><span>Libros en curso</span></div></div><div class="mini-stat"><div class="mini-icon">'+ico('check')+'</div><div><strong>'+completed+'</strong><span>Libros terminados</span></div></div></div><div class="chart-panel"><div class="card-row"><div><h3>Tiempo de lectura · últimos 7 días</h3><p>Minutos registrados mientras el lector está abierto.</p></div><span class="status-pill">'+sessionCount+' sesiones</span></div><div class="chart-bars">'+week.map(d=>'<div class="chart-col" title="'+d.minutes+' minutos"><span class="small">'+(d.minutes||'')+'</span><div class="chart-bar" style="height:'+Math.max(4,d.minutes/max*150)+'px"></div><label>'+d.label+'</label></div>').join('')+'</div></div><div class="section-head"><div><h2>Tu recorrido</h2><p>Los libros que forman parte de tu historia.</p></div></div>'+(state.books.filter(b=>b.progress>0).length?'<div class="book-grid">'+state.books.filter(b=>b.progress>0).slice(0,6).map(bookCard).join('')+'</div>':'<div class="empty"><div class="empty-icon">'+ico('stats')+'</div><h3>Acá empieza tu recorrido</h3><p>A medida que leas, vas a encontrar tus estadísticas y progreso.</p></div>')+'<div class="footer-note">Las estadísticas se guardan en este dispositivo y comienzan a registrarse al abrir y cerrar el lector.</div>'}
function selectSetting(key,options){return '<select class="select setting-select" data-setting="'+key+'">'+options.map(o=>'<option value="'+o[0]+'" '+(String(state.settings[key])===String(o[0])?'selected':'')+'>'+o[1]+'</option>').join('')+'</select>'}
function settingRow(title,desc,control){return '<div class="setting-row"><div><div class="setting-name">'+title+'</div><div class="setting-desc">'+desc+'</div></div>'+control+'</div>'}
function settingsPage(){const s=state.settings;return '<div class="page-head"><div><p class="eyebrow">A TU MANERA</p><h1>Configuración</h1><p class="sub">Hacé de cada lectura un momento cómodo y personal.</p></div></div><div class="settings-grid"><section class="settings-panel"><div><h3>Lectura</h3><p class="help">Personalizá el aspecto de tus libros.</p></div>'+settingRow('Tema del lector','Elegí el ambiente de lectura.',selectSetting('readerTheme',[['light','Claro'],['sepia','Sepia'],['dark','Oscuro']]))+settingRow('Tamaño del texto','Para EPUB y libro de muestra.',selectSetting('fontSize',[[16,'16 px'],[18,'18 px'],[19,'19 px'],[21,'21 px'],[23,'23 px'],[26,'26 px']]))+settingRow('Interlineado','Espaciado entre líneas.',selectSetting('lineHeight',[[1.4,'Compacto'],[1.7,'Normal'],[2,'Amplio']]))+settingRow('EPUB','Cómo pasar entre páginas.',selectSetting('epubFlow',[['paginated','Por páginas'],['scrolled-doc','Desplazamiento']]))+'</section><section class="settings-panel"><div><h3>Voz y pantalla</h3><p class="help">Escuchá con la voz de tu navegador.</p></div>'+settingRow('Velocidad de lectura','Texto a voz del dispositivo.',selectSetting('voiceSpeed',[[.75,'0,75 ×'],[1,'1 ×'],[1.25,'1,25 ×'],[1.5,'1,5 ×'],[2,'2 ×']]))+settingRow('Mantener pantalla encendida','Disponible en navegadores compatibles.','<button class="toggle '+(s.keepAwake?'on':'')+'" data-toggle="keepAwake" aria-label="Mantener pantalla encendida" aria-pressed="'+s.keepAwake+'"></button>')+settingRow('Modo de inactividad','Atenúa la lectura sin apagar el dispositivo.',selectSetting('smartTimeout',[[0,'Desactivado'],[5,'5 min'],[15,'15 min'],[20,'20 min'],[30,'30 min'],[45,'45 min']]))+'</section><section class="settings-panel"><div><h3>Biblioteca y datos</h3><p class="help">Todo permanece en este navegador.</p></div>'+settingRow('Objetivo diario','Minutos de lectura por día.',selectSetting('goalMinutes',[[10,'10 min'],[15,'15 min'],[20,'20 min'],[30,'30 min'],[45,'45 min'],[60,'60 min'],[90,'90 min']]))+settingRow('Orden habitual','Orden de las portadas.',selectSetting('sort',[['recent','Recientes'],['title','Título'],['author','Autor'],['progress','Progreso'],['added','Fecha de carga']]))+settingRow('Exportar mis datos','Descargá progreso, notas y preferencias.','<button class="tiny-btn" data-action="export">'+ico('download')+' Exportar</button>')+settingRow('Importar respaldo JSON','Recuperá libros y apuntes guardados (sin archivos PDF/EPUB).','<button class="tiny-btn" data-action="import-backup">'+ico('upload')+' Importar</button>')+settingRow('Borrar mis datos','Elimina archivos y apuntes locales.','<button class="danger-btn" data-action="reset">Borrar todo</button>')+'</section><section class="settings-panel"><div><h3>Privacidad y sincronización</h3><p class="help">Primera versión · almacenamiento local</p></div><p class="about-note">Tus PDF, EPUB, apuntes y progreso se almacenan en <strong>este dispositivo mediante IndexedDB</strong>. No se envían archivos ni se crean cuentas. Borrar los datos del sitio puede eliminar tu biblioteca.</p><p class="about-note">La <strong>sincronización entre dispositivos y el inicio de sesión</strong> están previstos para una etapa con backend seguro; todavía no están activos.</p><div class="hint">Consejo: conservá una copia de tus PDF y EPUB originales. La exportación de datos no incluye los archivos de los libros.</div></section></div>'}
function detailModal(b){if(!b)return '';const pieces=annotationsFor(b.id);const missing=!b.sample&&b.missingFile;return `<div class="modal-scrim" id="detail-scrim"><div class="modal" role="dialog" aria-modal="true" aria-label="Detalle del libro"><button class="icon-btn modal-close" data-action="close-detail" aria-label="Cerrar">${ico('x')}</button><div class="detail-top">${cover(b,'detail-cover')}<div><p class="detail-kicker">${esc(b.format)} · ${b.sample?'Libro de muestra':'Tu biblioteca'}</p><h1>${esc(b.title)}</h1><p class="detail-author">${esc(b.author||'Autor desconocido')}</p><p class="small" style="margin:18px 0 5px">${b.progress>=100?'Lectura terminada':b.progress>0?'Tu progreso':'Todavía no empezaste'}</p><div class="progress-row"><div class="progress-track"><div class="progress-fill" style="width:${b.progress||0}%"></div></div><span>${Math.round(b.progress||0)}%</span></div><div class="detail-actions"><button class="primary-btn" data-action="read" data-id="${esc(b.id)}">${ico('book')} ${b.progress?'Seguir leyendo':'Comenzar a leer'}</button><button class="secondary-btn" data-action="favorite" data-id="${esc(b.id)}">${ico('heart')} ${b.favorite?'Quitar favorito':'Favorito'}</button></div></div></div>
 ${missing?`<p class="relink-warning">Este libro se restauró sin el archivo original. <button data-action="relink-file" data-id="${esc(b.id)}">Volver a vincular PDF/EPUB</button></p>`:''}
 <div class="detail-meta"><div><span>Agregado</span><strong>${fmtDate(b.addedAt)}</strong></div><div><span>Última lectura</span><strong>${fmtDate(b.lastOpened)}</strong></div><div><span>Tiempo leído</span><strong>${prettyTime(b.time||0)}</strong></div></div><div class="detail-custom"><div class="custom-row"><label for="detail-collection">Colección</label><select id="detail-collection" data-book-collection="${esc(b.id)}"><option value="">Sin colección</option>${state.collections.map(c=>`<option value="${esc(c.id)}" ${(b.collections||[]).includes(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select><button class="tiny-btn" data-action="new-collection">${ico('plus')} Crear</button></div><div class="custom-row"><label for="book-tags">Etiquetas</label><input id="book-tags" data-book-tags="${esc(b.id)}" value="${esc((b.tags||[]).join(', '))}" placeholder="Ej: historia, trabajo, ficción" /><button class="tiny-btn" data-action="save-tags" data-id="${esc(b.id)}">Guardar</button></div><div class="custom-row"><label for="reading-deadline">Fecha objetivo</label><input type="date" id="reading-deadline" data-book-date="${esc(b.id)}" value="${esc(b.targetDate||'')}"/><button class="tiny-btn" data-action="save-target" data-id="${esc(b.id)}">Guardar</button></div></div>
 <div class="detail-menu"><button class="tiny-btn" data-action="queue" data-id="${esc(b.id)}">${ico('clock')} ${b.readLater?'Quitar de leer después':'Leer después'}</button><button class="tiny-btn" data-action="new-note" data-id="${esc(b.id)}">${ico('note')} Nueva nota</button><button class="tiny-btn" data-action="edit-book" data-id="${esc(b.id)}">${ico('edit')} Editar datos</button><button class="tiny-btn" data-action="finish" data-id="${esc(b.id)}">${ico('check')} ${b.progress===100?'Reabrir lectura':'Marcar terminado'}</button>${!b.sample?`<button class="tiny-btn danger" data-action="delete-book" data-id="${esc(b.id)}">${ico('trash')} Eliminar libro</button>`:''}</div>${pieces.length?`<div class="section-head"><h2>Apuntes de este libro</h2><span class="small">${pieces.length}</span></div><div class="study-grid">${pieces.slice(0,3).map(annotationCard).join('')}</div>`:'<div class="hint">Seleccioná texto durante la lectura para guardar notas, fragmentos o resaltados.</div>'}</div></div>`}
function readerMarkup(){const b=state.reader;if(!b)return '';const theme=state.settings.readerTheme;return `<div id="reader" class="reader" data-theme="${esc(theme)}"><header class="reader-bar"><div class="reader-left"><button class="icon-btn" title="Volver a biblioteca" data-action="close-reader">${ico('back')}</button><div><div class="reader-title">${esc(b.title)}</div><span>${esc(b.author||'')}</span></div></div><div class="reader-tools"><button class="icon-btn" data-action="bookmark" title="Guardar marcador de lectura">${ico('bookmark')}</button><button class="icon-btn" data-action="speak" title="Leer en voz alta">${ico('volume')}</button><button class="icon-btn" data-action="reader-note" title="Nueva nota">${ico('note')}</button><button class="icon-btn" data-action="toggle-side" title="Herramientas de lectura">${ico('settings')}</button><button class="icon-btn" data-action="fullscreen" title="Pantalla completa">${ico('full')}</button></div></header><div class="reader-main"><div class="reader-stage" id="reader-stage">${b.format==='EPUB'?'<div class="reader-epub" id="epub-stage"></div>':b.format==='DEMO'?'<div class="reader-demo" id="demo-stage"></div>':'<div id="pdf-stage" style="width:100%;display:flex;flex-direction:column;align-items:center;justify-content:flex-start"><p class="small">Preparando documento PDF…</p></div>'}</div><div id="reader-side" class="reader-side ${!state.readerSide?'hidden':''}">${readerSideMarkup()}</div></div><div id="selection-menu" class="selection-menu hidden"><button data-action="selection-copy">Copiar</button><button data-action="selection-highlight">Resaltar</button><button data-action="selection-fragment">Guardar fragmento</button><button data-action="selection-note">Crear nota</button><button data-action="selection-speak">Escuchar</button></div><div id="tts-dock" class="tts-dock hidden"><button data-action="tts-prev">${ico('back')}</button><button data-action="tts-toggle" id="tts-toggle">${ico('pause')}</button><button data-action="tts-next">${ico('chevron')}</button><span id="tts-caption">Leyendo en voz alta</span><button data-action="tts-sleep">${ico('moon')}</button><button data-action="tts-stop">${ico('x')}</button></div><footer class="reader-bottom"><div class="reader-controls"><button class="icon-btn" data-action="prev">${ico('back')}</button><span class="reader-counter" id="reader-count">Cargando…</span><button class="icon-btn" data-action="next">${ico('chevron')}</button></div><div class="reader-progress"><div class="progress-track"><div class="progress-fill" id="reader-progress-fill" style="width:${b.progress}%"></div></div><small id="reader-percent">${Math.round(b.progress)}%</small></div><div class="reader-controls">${b.format==='PDF'?'<button class="icon-btn" data-action="zoom-out" title="Alejar">−</button><button class="icon-btn" data-action="zoom-in" title="Acercar">+</button><button class="icon-btn" data-action="rotate" title="Rotar">↻</button>':'<button class="icon-btn" data-action="font-down" title="Texto más pequeño">A−</button><button class="icon-btn" data-action="font-up" title="Texto más grande">A+</button>'}</div></footer></div>`}
function readerSideMarkup(){if(!state.readerSide)return '';const b=state.reader,ann=annotationsFor(b.id);const head=`<div class="side-tabs"><button data-side="notes" class="chip ${state.readerSide==='notes'?'active':''}">Apuntes</button><button data-side="bookmarks" class="chip ${state.readerSide==='bookmarks'?'active':''}">Marcadores</button><button data-side="reading" class="chip ${state.readerSide==='reading'?'active':''}">Lectura</button></div>`;
 if(state.readerSide==='notes')return head+`<div class="reader-side-content"><h3>Mis apuntes</h3><p>Guardá lo que querés volver a encontrar.</p><button class="secondary-btn" data-action="reader-note">${ico('plus')} Nueva nota</button>${ann.map(a=>`<div class="reader-note" data-action="jump" data-id="${esc(a.id)}">${esc(a.text.slice(0,190))}<small>${esc(a.type==='note'?'Nota':a.type==='fragment'?'Fragmento':'Resaltado')} · ${esc(a.locationLabel||'')}</small></div>`).join('')}</div>`;
 if(state.readerSide==='bookmarks')return head+`<div class="reader-side-content"><h3>Marcadores</h3><p>Volvé a tus páginas señaladas.</p><button class="secondary-btn" data-action="bookmark">${ico('plus')} Marcar esta página</button>${(b.bookmarks||[]).length?(b.bookmarks||[]).map(m=>`<div class="bookmark-entry"><button data-action="go-bookmark" data-id="${esc(m.id)}">${ico('bookmark')} ${esc(m.label)}</button><button data-action="delete-bookmark" data-id="${esc(m.id)}" title="Borrar marcador">${ico('x')}</button></div>`).join(''):'<p>Sin marcadores todavía.</p>'}</div>`;
 return head+`<div class="reader-side-content"><h3>Tu lectura</h3><div class="reader-actions"><button class="secondary-btn" data-action="speak">${ico('volume')} Escuchar texto</button><button class="secondary-btn" data-action="tts-sleep">${ico('moon')} Temporizador de sueño</button><button class="secondary-btn" data-action="reader-theme">${ico('sun')} Cambiar tema</button></div><div style="margin-top:22px"><div class="setting-name">Velocidad de voz</div>${selectSetting('voiceSpeed',[[.75,'0,75 ×'],[1,'1 ×'],[1.25,'1,25 ×'],[1.5,'1,5 ×'],[2,'2 ×']])}</div><p>Atajos: ← → páginas, espacio para voz, F pantalla completa, N nueva nota.</p></div>`}
function refreshReaderSide(){const s=$('#reader-side');if(s){s.classList.toggle('hidden',!state.readerSide);s.innerHTML=readerSideMarkup()}}

function readingStreak(){const days=new Set(state.sessions.filter(s=>s.duration>0).map(s=>dateKey(s.start)));let day=0,streak=0;if(!days.has(dateKey()))day=1;while(days.has(dateKey(Date.now()-day*86400000))){streak++;day++}return streak}
function allTags(){return [...new Set(state.books.flatMap(b=>b.tags||[]))].sort((a,b)=>a.localeCompare(b,'es'))}
async function saveCollections(){await putOne('prefs',{id:'collections',items:state.collections})}
function downloadText(name,text,mime='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type:mime}));const anchor=document.createElement('a');anchor.href=url;anchor.download=name;document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportMarkdown(){const valid=state.annotations.filter(a=>state.studyFilter==='all'||a.type===state.studyFilter);const blocks=['# MiLibroPDF — Mis apuntes','Exportado el '+fmtDate(Date.now()),...valid.map(a=>{const b=bookBy(a.bookId);return '## '+(b?.title||'Nota personal')+'\n**'+({note:'Nota',fragment:'Fragmento',highlight:'Resaltado'}[a.type]||'Apunte')+'** · '+(a.locationLabel||'')+' · '+fmtDate(a.createdAt)+'\n\n'+a.text.replace(/\n/g,'\n\n')+'\n'})];downloadText('MiLibroPDF-apuntes-'+dateKey()+'.md',blocks.join('\n\n'),'text/markdown;charset=utf-8');toast('Apuntes exportados en Markdown')}
function collectionsPage(){return `<div class="page-head"><div><p class="eyebrow">ORDEN A TU MANERA</p><h1>Mis colecciones<span class="period">.</span></h1><p class="sub">Armá estanterías para tus proyectos, géneros o estados de ánimo.</p></div><button class="primary-btn" data-action="new-collection">${ico('plus')} Nueva colección</button></div><div class="collections-grid">${state.collections.map(c=>{const books=state.books.filter(b=>(b.collections||[]).includes(c.id));return `<article class="collection-card"><div class="collection-symbol">${ico('library')}</div><h3>${esc(c.name)}</h3><p>${books.length} ${books.length===1?'libro':'libros'}</p><div class="collection-preview">${books.slice(0,3).map(b=>`<span class="mini-cover ${coverVariant(b)}"></span>`).join('')||'<span>Tu próximo espacio de lectura</span>'}</div><div class="collection-buttons"><button data-action="view-collection" data-id="${esc(c.id)}">Ver libros ${ico('arrow')}</button><button title="Renombrar" data-action="rename-collection" data-id="${esc(c.id)}">${ico('edit')}</button><button title="Eliminar" data-action="delete-collection" data-id="${esc(c.id)}">${ico('trash')}</button></div></article>`}).join('')}<button class="collection-add" data-action="new-collection">${ico('plus')}<strong>Crear nueva colección</strong><span>Ordená tus libros por tema o proyecto.</span></button></div>`}
function paletteEntries(){return [...[['Ir a Inicio','home','home'],['Abrir Biblioteca','library','library'],['Ver Colecciones','collections','grid'],['Ver Apuntes','study','quote'],['Ver Estadísticas','stats','stats'],['Abrir Configuración','settings','settings']].map(x=>({label:x[0],nav:x[1],icon:x[2]})),{label:'Agregar libros PDF o EPUB',action:'import',icon:'plus'},...state.books.map(b=>({label:b.title,sub:b.author||'',id:b.id,icon:'book'}))]}
function paletteMarkup(){const q=state.paletteQuery.toLocaleLowerCase('es');const items=paletteEntries().filter(item=>(item.label+' '+(item.sub||'')).toLocaleLowerCase('es').includes(q)).slice(0,11);return `<div id="palette-overlay" class="palette-overlay"><div class="palette-panel" role="dialog" aria-modal="true" aria-label="Búsqueda rápida"><label class="palette-input">${ico('search')}<input id="palette-search" placeholder="Buscar libros, navegar o ejecutar acciones..." value="${esc(state.paletteQuery)}" autocomplete="off" /><kbd>ESC</kbd></label><div class="palette-entries">${items.length?items.map(x=>`<button data-palette-go="${esc(x.nav||x.action||x.id)}" data-palette-kind="${x.nav?'nav':x.action?'action':'book'}">${ico(x.icon)}<span>${esc(x.label)}${x.sub?'<small>'+esc(x.sub)+'</small>':''}</span>${ico('arrow')}</button>`).join(''):'<p class="palette-empty">No encontramos resultados. Probá con otro término.</p>'}</div><div class="palette-foot">Búsqueda rápida · Ctrl + K para abrir</div></div></div>`}
async function importBackup(file){if(!file)return;let data;try{data=JSON.parse(await file.text())}catch{toast('El respaldo no es un JSON válido.');return}if(data.app!=='MiLibroPDF Web'||!Array.isArray(data.books)||!Array.isArray(data.annotations)||!Array.isArray(data.sessions)){toast('El archivo no es un respaldo compatible de MiLibroPDF.');return}if(!confirm('¿Importar este respaldo? Se combinará con tu biblioteca actual, sin borrar archivos ni notas existentes. Los libros restaurados necesitarán sus PDF/EPUB originales.'))return;let added=0;for(const b of data.books.slice(0,5000)){if(!b?.id||!['PDF','EPUB'].includes(b.format))continue;const existing=bookBy(b.id);if(existing){if(Number(b.progress)>Number(existing.progress||0)){existing.progress=b.progress;existing.position=b.position;existing.page=b.page;await putOne('books',existing)}continue}const safe={...b,id:String(b.id),title:String(b.title||'Sin título').slice(0,300),author:String(b.author||'').slice(0,300),format:b.format,fileName:String(b.fileName||''),missingFile:true,bookmarks:Array.isArray(b.bookmarks)?b.bookmarks.slice(0,500):[],collections:Array.isArray(b.collections)?b.collections:[],tags:Array.isArray(b.tags)?b.tags:[]};await putOne('books',safe);state.books.push(safe);added++}let notes=0;for(const a of data.annotations.slice(0,10000)){if(!a?.id||!['note','fragment','highlight'].includes(a.type)||state.annotations.some(x=>x.id===a.id))continue;const safe={...a,text:String(a.text||'').slice(0,100000)};await putOne('annotations',safe);state.annotations.push(safe);notes++}for(const item of data.sessions.slice(0,30000)){if(!item?.id||state.sessions.some(x=>x.id===item.id)||!Number.isFinite(Number(item.duration)))continue;await putOne('sessions',item);state.sessions.push(item)}if(Array.isArray(data.collections)){for(const c of data.collections){if(c?.id&&c?.name&&!state.collections.some(x=>x.id===c.id))state.collections.push({id:String(c.id),name:String(c.name)})}await saveCollections()}state.view='library';render();toast(`Respaldo importado: ${added} libros, ${notes} apuntes. Vinculá los archivos originales para leer.`)}
async function relinkFile(id){const b=bookBy(id);if(!b)return;const input=$('#relink-input');input.dataset.id=id;input.accept=b.format==='PDF'?'.pdf,application/pdf':'.epub,application/epub+zip';input.click()}
async function saveRelinkedFile(file,id){const b=bookBy(id);if(!b||!file)return;if(!file.name.toLowerCase().endsWith('.'+b.format.toLowerCase())){toast('Formato incorrecto. Seleccioná un '+b.format+'.');return}await putOne('files',{id,blob:file});b.missingFile=false;b.fileName=file.name;b.size=file.size;await putOne('books',b);render();toast('Archivo vinculado. Ya podés continuar leyendo.')}
async function createBookmark(){const b=state.reader;if(!b)return;const position=currentPos(),label=locationLabel();b.bookmarks=b.bookmarks||[];if(b.bookmarks.some(x=>String(x.position)===String(position))){toast('Esta ubicación ya está marcada.');return}b.bookmarks.push({id:uid(),position,page:state.page,label,createdAt:Date.now()});await putOne('books',b);state.readerSide='bookmarks';refreshReaderSide();toast('Marcador guardado')}
async function goBookmark(id){const b=state.reader,m=b?.bookmarks?.find(x=>x.id===id);if(!m)return;if(b.format==='PDF'){state.page=m.page;await renderPdfPage()}else if(b.format==='DEMO'){showDemoPage(Number(m.position))}else if(state.rendition){await state.rendition.display(m.position)}state.readerSide='';refreshReaderSide()}
async function deleteBookmark(id){const b=state.reader;if(!b)return;b.bookmarks=(b.bookmarks||[]).filter(x=>x.id!==id);await putOne('books',b);refreshReaderSide();toast('Marcador eliminado')}
async function newCollection(){const name=prompt('Nombre de la nueva colección:','');if(name===null)return;const clean=name.trim().slice(0,60);if(!clean){toast('La colección necesita un nombre.');return}if(state.collections.some(c=>c.name.toLocaleLowerCase('es')===clean.toLocaleLowerCase('es'))){toast('Ya existe una colección con ese nombre.');return}state.collections.push({id:uid(),name:clean});await saveCollections();render();toast('Colección creada')}
async function renameCollection(id){const c=state.collections.find(x=>x.id===id);if(!c)return;const name=prompt('Nuevo nombre de la colección:',c.name);if(name===null||!name.trim())return;c.name=name.trim().slice(0,60);await saveCollections();render();toast('Colección renombrada')}
async function deleteCollection(id){const c=state.collections.find(x=>x.id===id);if(!c||!confirm(`¿Eliminar la colección “${c.name}”? Los libros no se borrarán.`))return;state.collections=state.collections.filter(x=>x.id!==id);await saveCollections();for(const b of state.books.filter(b=>(b.collections||[]).includes(id))){b.collections=b.collections.filter(x=>x!==id);await putOne('books',b)}if(state.collectionFilter===id)state.collectionFilter='all';render();toast('Colección eliminada; los libros se conservaron')}
async function changeGoal(){const current=Number(state.settings.goalMinutes)||20;const value=prompt('¿Cuántos minutos querés leer por día? (1 a 240)',String(current));if(value===null)return;const n=Number(value);if(!Number.isInteger(n)||n<1||n>240){toast('Ingresá un número entre 1 y 240.');return}state.settings.goalMinutes=n;await savePrefs();render();toast('Objetivo diario guardado')}

async function savePrefs(){await putOne('prefs',{id:'settings',...state.settings})}
function updateReaderProgress(){const b=state.reader;if(!b)return;const fill=$('#reader-progress-fill');if(fill)fill.style.width=Math.min(100,Math.max(0,b.progress||0))+'%';const pct=$('#reader-percent');if(pct)pct.textContent=Math.round(b.progress)+'%';const counter=$('#reader-count');if(counter)counter.textContent=b.format==='PDF'?'Página '+state.page+' de '+(b.totalPages||'?'):b.format==='DEMO'?'Capítulo '+(state.demoPage+1)+' de '+sampleChapters.length:Math.round(b.progress)+'% leído'}
function markLocation(position,page,percentage){const b=state.reader;if(!b)return;b.position=position;b.page=page??b.page;b.progress=Math.max(0,Math.min(100,Number(percentage)||0));b.status=b.progress>=100?'finished':b.progress>0?'reading':'unread';b.lastOpened=Date.now();updateReaderProgress();clearTimeout(markLocation.timer);markLocation.timer=setTimeout(()=>putOne('books',b).catch(console.warn),500)}
let pdfjsPromise;
function pdfLib(){if(!pdfjsPromise)pdfjsPromise=import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.mjs').then(m=>{m.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.mjs';return m});return pdfjsPromise}
async function getBookFile(b){const item=await getOne('files',b.id);if(!item||!item.blob)throw Error('No se encontró el archivo en este navegador. Volvé a importarlo.');return item.blob}
async function startReader(id,positionOverride){const b=bookBy(id);if(!b){toast('No encontramos ese libro.');return}if(state.reader)await closeReader();state.detail=null;state.reader=b;state.readerSide='';state.selectedText='';state.selectedPos=null;state.page=Math.max(1,b.page||1);state.demoPage=Math.max(0,Math.min(sampleChapters.length-1,Math.floor(b.position||0)));state.pdfScale=1;state.pdfRotation=0;state.sessionStart=Date.now();state.sessionPage=b.page||1;b.lastOpened=Date.now();await putOne('books',b);render();try{if(b.format==='PDF')await openPDF(b,positionOverride);else if(b.format==='EPUB')await openEPUB(b,positionOverride);else showDemoPage(positionOverride===undefined?state.demoPage:Number(positionOverride)||0);updateReaderProgress();if(state.settings.keepAwake)requestWakeLock()}catch(e){console.error(e);const stage=$('#reader-stage');if(stage)stage.innerHTML='<div class="reader-message"><b>No pudimos abrir este libro.</b><p>'+esc(e.message||'Error al cargar el archivo')+'</p><button class="secondary-btn" data-action="close-reader">Volver a biblioteca</button></div>';toast('No se pudo abrir el archivo. Revisá si está dañado.')}}
async function openPDF(b,positionOverride){const lib=await pdfLib();const file=await getBookFile(b);const bytes=await file.arrayBuffer();const job=lib.getDocument({data:new Uint8Array(bytes)});state.pdf=await job.promise;b.totalPages=state.pdf.numPages;state.page=typeof positionOverride==='number'?Math.min(Math.max(1,positionOverride),b.totalPages):Math.min(Math.max(1,b.page||1),b.totalPages);await renderPdfPage()}
async function renderPdfPage(){if(!state.pdf||!state.reader)return;const lib=await pdfLib();const page=await state.pdf.getPage(state.page);state.pdfPage=page;const host=$('#pdf-stage');if(!host)return;host.innerHTML='';let viewport=page.getViewport({scale:1,rotation:state.pdfRotation});const maxWidth=Math.max(270,host.getBoundingClientRect().width-25);const scale=Math.min(1.7,maxWidth/viewport.width)*state.pdfScale;viewport=page.getViewport({scale,rotation:state.pdfRotation});const layer=document.createElement('div');layer.className='reader-page';layer.style.width=viewport.width+'px';layer.style.height=viewport.height+'px';const canvas=document.createElement('canvas');const ctx=canvas.getContext('2d',{alpha:false});const outputScale=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.floor(viewport.width*outputScale);canvas.height=Math.floor(viewport.height*outputScale);canvas.style.width=viewport.width+'px';canvas.style.height=viewport.height+'px';layer.appendChild(canvas);host.appendChild(layer);await page.render({canvasContext:ctx,viewport,transform:outputScale!==1?[outputScale,0,0,outputScale,0,0]:null}).promise;try{const text=await page.getTextContent();if(text.items.length){const textLayer=document.createElement('div');textLayer.className='textLayer';textLayer.style.setProperty('--scale-factor',String(viewport.scale));layer.appendChild(textLayer);if(lib.TextLayer){const painter=new lib.TextLayer({textContentSource:text,container:textLayer,viewport});await painter.render()}else{for(const item of text.items){const span=document.createElement('span');span.textContent=item.str;const tx=lib.Util.transform(viewport.transform,item.transform);span.style.left=tx[4]+'px';span.style.top=tx[5]-Math.abs(tx[3])+'px';span.style.fontSize=Math.abs(tx[3])+'px';textLayer.appendChild(span)}}}}catch(e){console.warn('Capa de texto no disponible:',e)}host.scrollTop=0;markLocation(state.page,state.page,state.pdf.numPages===1?100:Math.round((state.page-1)/(state.pdf.numPages-1)*100))}
async function openEPUB(b,override){if(typeof window.ePub!=='function')throw Error('El módulo EPUB no cargó. Revisá tu conexión y volvé a intentarlo.');const file=await getBookFile(b);const buffer=await file.arrayBuffer();state.epub=window.ePub(buffer);await state.epub.ready;const host=$('#epub-stage');if(!host)return;state.rendition=state.epub.renderTo(host,{width:'100%',height:'100%',flow:state.settings.epubFlow,spread:'none'});applyEpubTheme();state.rendition.on('selected',(cfi,contents)=>{const s=contents.window.getSelection().toString().trim();if(s){state.selectedText=s;state.selectedPos=cfi;showSelectionMenu()}});state.rendition.on('relocated',loc=>{let pct=Number(loc.start?.percentage)*100;if(!Number.isFinite(pct))try{pct=state.epub.locations.percentageFromCfi(loc.start.cfi)*100}catch{}if(!Number.isFinite(pct))pct=state.reader.progress;markLocation(loc.start?.cfi||'',0,pct)});await state.rendition.display(override||b.position||undefined);state.epub.locations.generate(1200).then(()=>{const cfi=state.rendition?.currentLocation()?.start?.cfi;if(cfi){const pct=state.epub.locations.percentageFromCfi(cfi)*100;if(Number.isFinite(pct))markLocation(cfi,0,pct)}}).catch(e=>console.warn('No se generaron ubicaciones EPUB:',e))}
function applyEpubTheme(){if(!state.rendition)return;const dark=state.settings.readerTheme==='dark';const light=state.settings.readerTheme==='light';const color=dark?'#efe6e2':light?'#303030':'#4b3f35';const bg=dark?'#222126':light?'#ffffff':'#f7f0e3';state.rendition.themes.default({'body':{'color':color+' !important','background':bg+' !important','font-family':'Georgia, serif !important','font-size':state.settings.fontSize+'px !important','line-height':state.settings.lineHeight+' !important','padding':'0 8px !important'},'::selection':{'background':'#f0c879'}});state.rendition.themes.fontSize(state.settings.fontSize+'px')}
function showDemoPage(n){state.demoPage=Math.max(0,Math.min(sampleChapters.length-1,n));const chapter=sampleChapters[state.demoPage];const host=$('#demo-stage');if(host){host.style.fontSize=state.settings.fontSize+'px';host.style.lineHeight=state.settings.lineHeight;host.innerHTML='<p class="eyebrow" style="font-size:10px">EL PLACER DE LEER</p><h2>'+esc(chapter.title)+'</h2>'+chapter.text.split('\n\n').map(p=>'<p>'+esc(p)+'</p>').join('')}markLocation(state.demoPage,state.demoPage+1,Math.round(state.demoPage/(sampleChapters.length-1)*100))}
async function nextPage(direction){if(!state.reader)return;dismissSelection();stopSpeech();if(state.reader.format==='PDF'){const newPage=state.page+direction;if(newPage>=1&&newPage<=state.pdf.numPages){state.page=newPage;await renderPdfPage()}}else if(state.reader.format==='EPUB'){if(state.rendition)await (direction>0?state.rendition.next():state.rendition.prev())}else{showDemoPage(state.demoPage+direction)}}
async function closeReader(){clearTimeout(markLocation.timer);stopSpeech();if(!state.reader)return;const b=state.reader;const secs=Math.max(0,Math.round((Date.now()-state.sessionStart)/1000));if(secs>=2){state.sessions.push({id:uid(),bookId:b.id,start:state.sessionStart,end:Date.now(),duration:secs,pages:Math.max(0,(b.page||0)-(state.sessionPage||0))});b.time=(b.time||0)+secs;await Promise.all([putOne('sessions',state.sessions[state.sessions.length-1]),putOne('books',b)])}if(state.rendition)try{state.rendition.destroy()}catch{}if(state.epub)try{state.epub.destroy()}catch{}if(state.pdf)try{await state.pdf.destroy()}catch{}state.rendition=null;state.epub=null;state.pdf=null;state.pdfPage=null;state.reader=null;state.readerSide='';if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});if(state.wakeLock)try{await state.wakeLock.release()}catch{}state.wakeLock=null;render()}
async function requestWakeLock(){if(!navigator.wakeLock||!state.reader)return;try{state.wakeLock=await navigator.wakeLock.request('screen')}catch(e){console.info('Wake Lock no disponible',e)}}
function showSelectionMenu(){const menu=$('#selection-menu');if(menu&&state.selectedText)menu.classList.remove('hidden')}
function dismissSelection(){state.selectedText='';state.selectedPos=null;$('#selection-menu')?.classList.add('hidden')}
function currentPos(){if(!state.reader)return null;return state.reader.format==='PDF'?state.page:state.reader.format==='DEMO'?state.demoPage:(state.rendition?.currentLocation()?.start?.cfi||state.reader.position||null)}
function locationLabel(){if(!state.reader)return '';return state.reader.format==='PDF'?'Página '+state.page:state.reader.format==='DEMO'?'Capítulo '+(state.demoPage+1):'Ubicación EPUB'}
async function addAnnotation(type,manual=false,bookId){const b=bookBy(bookId)||state.reader||null;const selected=manual?'':state.selectedText;let text=selected;if(type==='note'){const value=prompt('Escribí tu nota:',selected?'Comentario sobre: '+selected.slice(0,65)+'\n':'');if(value===null)return;text=value.trim();if(!text)return}else if(!text){const value=prompt(type==='highlight'?'Texto que querés resaltar:':'Guardá un fragmento:','');if(value===null)return;text=value.trim();if(!text)return}const ann={id:uid(),bookId:b?.id||null,type,text,selectedText:type==='note'?selected:'',position:state.selectedPos||currentPos(),page:b?.format==='PDF'?state.page:null,locationLabel:b?locationLabel():'Nota personal',createdAt:Date.now(),updatedAt:Date.now()};state.annotations.unshift(ann);await putOne('annotations',ann);dismissSelection();if(state.reader){refreshReaderSide();toast(type==='note'?'Nota guardada':type==='fragment'?'Fragmento guardado':'Resaltado guardado')}else{state.detail=null;render();toast('Guardado en tus apuntes')}}
async function jumpToAnnotation(id){const a=state.annotations.find(a=>a.id===id);if(!a)return;const b=bookBy(a.bookId);if(!b){toast('Esta nota no está asociada a un libro.');return}if(state.reader?.id===b.id){if(b.format==='PDF'&&a.page){state.page=a.page;await renderPdfPage()}else if(b.format==='EPUB'&&a.position){await state.rendition.display(a.position)}else if(b.format==='DEMO'&&a.position!==null){showDemoPage(Number(a.position))}return}await startReader(b.id,a.position??a.page)}
function getReaderText(){const b=state.reader;if(!b)return '';if(b.format==='DEMO')return sampleChapters[state.demoPage].text;if(b.format==='EPUB'){const contents=state.rendition?.getContents?.();return (contents||[]).map(c=>c.document?.body?.innerText||c.document?.body?.textContent||'').join(' ')}return ''}
async function getSpeakText(){if(state.selectedText)return state.selectedText;if(state.reader?.format==='PDF'){const page=await state.pdf.getPage(state.page);const items=(await page.getTextContent()).items;return items.map(x=>x.str+(x.hasEOL?'\n':' ')).join(' ')}return getReaderText()}
async function startSpeech(){if(!state.reader)return;if(!('speechSynthesis' in window)){toast('Tu navegador no admite lectura en voz alta.');return}stopSpeech();const text=String(await getSpeakText()||'').replace(/\s+/g,' ').trim();if(!text){toast('No encontramos texto seleccionable en esta página. Es posible que sea un PDF escaneado.');return}state.phrases=text.match(/[^.!?]+(?:[.!?]+|$)/g)?.map(x=>x.trim()).filter(Boolean)||[text];state.phraseIndex=0;state.speaking=true;state.paused=false;renderTtsDock();speakPhrase()}
function speakPhrase(){if(!state.speaking)return;const t=state.phrases[state.phraseIndex];if(!t){stopSpeech();return}speechSynthesis.cancel();const utt=new SpeechSynthesisUtterance(t);utt.lang='es-AR';utt.rate=Number(state.settings.voiceSpeed);const voices=speechSynthesis.getVoices();const chosen=voices.find(v=>v.name===state.settings.voiceName)||voices.find(v=>v.lang.toLowerCase().startsWith('es'));if(chosen)utt.voice=chosen;utt.onend=()=>{if(!state.speaking||state.paused)return;state.phraseIndex++;if(state.phraseIndex>=state.phrases.length){stopSpeech();return}speakPhrase()};utt.onerror=(e)=>{if(e.error!=='interrupted'&&e.error!=='canceled'){console.warn('TTS:',e.error);stopSpeech()}};$('#tts-caption').textContent=t;speechSynthesis.speak(utt)}
function renderTtsDock(){const el=$('#tts-dock');if(!el)return;el.classList.toggle('hidden',!state.speaking);const b=$('#tts-toggle');if(b)b.innerHTML=ico(state.paused?'play':'pause')}
function toggleSpeech(){if(!state.speaking){startSpeech();return}if(state.paused){state.paused=false;speechSynthesis.resume()}else{state.paused=true;speechSynthesis.pause()}renderTtsDock()}
function stopSpeech(){state.speaking=false;state.paused=false;state.phrases=[];clearTimeout(state.sleepTimeout);state.sleepTimeout=null;if('speechSynthesis' in window)speechSynthesis.cancel();renderTtsDock()}
function skipPhrase(delta){if(!state.speaking)return;state.phraseIndex=Math.max(0,Math.min(state.phrases.length-1,state.phraseIndex+delta));state.paused=false;speakPhrase();renderTtsDock()}
function setSleep(){const choices='5, 10, 15, 20, 30, 45 o 60';const answer=prompt('¿En cuántos minutos querés detener la voz? ('+choices+')\nIngresá 0 para cancelar:',String(state.settings.sleep||15));if(answer===null)return;const minutes=Number(answer);if(minutes===0){clearTimeout(state.sleepTimeout);state.sleepTimeout=null;toast('Temporizador desactivado');return}if(![5,10,15,20,30,45,60].includes(minutes)){toast('Elegí uno de los valores disponibles.');return}state.settings.sleep=minutes;savePrefs();clearTimeout(state.sleepTimeout);state.sleepTimeout=setTimeout(()=>{stopSpeech();toast('Terminó el temporizador de lectura')},minutes*60000);toast('La voz se detendrá en '+minutes+' minutos')}
async function importFiles(files){const valid=Array.from(files||[]).filter(f=>/\.(pdf|epub)$/i.test(f.name));if(!valid.length){toast('Elegí archivos PDF o EPUB.');return}let count=0;for(const file of valid){try{const format=file.name.toLowerCase().endsWith('.epub')?'EPUB':'PDF';const id=uid();let title=file.name.replace(/\.(pdf|epub)$/i,'').replace(/[_-]+/g,' ').trim();let author='Autor desconocido';let totalPages=0;if(format==='PDF'){try{const lib=await pdfLib();const copy=new Uint8Array(await file.arrayBuffer());const doc=await lib.getDocument({data:copy}).promise;totalPages=doc.numPages;try{const info=await doc.getMetadata();if(info.info?.Title?.trim())title=info.info.Title.trim();if(info.info?.Author?.trim())author=info.info.Author.trim()}catch{}await doc.destroy()}catch(e){console.warn('Metadatos PDF:',e)}}else if(typeof window.ePub==='function'){let epub;try{epub=window.ePub(await file.arrayBuffer());const info=await epub.loaded.metadata;if(info.title)title=info.title;if(info.creator)author=info.creator}catch(e){console.warn('Metadatos EPUB:',e)}finally{try{epub?.destroy()}catch{}}}const b={id,title,author,format,fileName:file.name,size:file.size,addedAt:Date.now(),lastOpened:0,position:format==='PDF'?1:'',page:1,totalPages,progress:0,status:'unread',favorite:false,archived:false,time:0,sample:false};await putOne('files',{id,blob:file});await putOne('books',b);state.books.push(b);count++}catch(e){console.error('Importación:',e);toast('Error al guardar '+file.name+': puede faltar espacio en el dispositivo.')}}state.view='library';state.filter='all';state.type='all';state.query='';render();if(count)toast(count===1?'Libro agregado a tu biblioteca':count+' libros agregados a tu biblioteca')}
async function editBook(id){const b=bookBy(id);if(!b)return;const title=prompt('Título del libro:',b.title);if(title===null)return;if(!title.trim()){toast('El título no puede estar vacío.');return}const author=prompt('Autor:',b.author||'');if(author===null)return;b.title=title.trim();b.author=author.trim()||'Autor desconocido';await putOne('books',b);render();toast('Datos del libro actualizados')}
async function deleteBook(id){const b=bookBy(id);if(!b||b.sample)return;if(!confirm('¿Eliminar “'+b.title+'” y todos sus apuntes? Esta acción no se puede deshacer.'))return;await deleteOne('books',id);await deleteOne('files',id);for(const a of annotationsFor(id))await deleteOne('annotations',a.id);state.annotations=state.annotations.filter(x=>x.bookId!==id);state.books=state.books.filter(x=>x.id!==id);state.detail=null;render();toast('Libro eliminado de este dispositivo')}
async function deleteAnnotation(id){const a=state.annotations.find(x=>x.id===id);if(!a||!confirm('¿Eliminar este apunte?'))return;await deleteOne('annotations',id);state.annotations=state.annotations.filter(x=>x.id!==id);if(state.reader)refreshReaderSide();else render();toast('Apunte eliminado')}
async function editAnnotation(id){const a=state.annotations.find(x=>x.id===id);if(!a)return;const value=prompt('Editar '+(a.type==='note'?'nota':'fragmento')+':',a.text);if(value===null||!value.trim())return;a.text=value.trim();a.updatedAt=Date.now();await putOne('annotations',a);if(state.reader)refreshReaderSide();else render();toast('Apunte actualizado')}
function exportData(){const data={app:'MiLibroPDF Web',version:1,exportedAt:new Date().toISOString(),notice:'Este respaldo incluye metadatos y apuntes, pero NO incluye archivos PDF o EPUB.',books:state.books.filter(b=>!b.sample),annotations:state.annotations,sessions:state.sessions,settings:state.settings,collections:state.collections};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='MiLibroPDF-datos-'+dateKey()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Datos exportados. Conservá también los archivos originales.')}
async function resetData(){if(!confirm('¿Borrar TODOS los libros, archivos, notas y estadísticas guardados en este navegador?'))return;if(!confirm('Es irreversible. ¿Confirmás el borrado total?'))return;for(const table of ['books','files','annotations','sessions','prefs'])await new Promise((res,rej)=>{const r=idbStore(table,'readwrite').clear();r.onsuccess=res;r.onerror=()=>rej(r.error)});state.books=[{...sampleBook}];state.annotations=[];state.sessions=[];state.settings={...defaultSettings};state.collections=[];state.detail=null;state.view='home';await putOne('books',state.books[0]);await savePrefs();render();toast('Biblioteca local reiniciada')}
async function act(name,id){const b=bookBy(id);switch(name){case'import':$('#file-input').click();break;case'palette':state.palette=true;state.paletteQuery='';render();break;case'new-collection':await newCollection();break;case'rename-collection':await renameCollection(id);break;case'delete-collection':await deleteCollection(id);break;case'view-collection':state.view='library';state.collectionFilter=id;render();break;case'queue':if(b){b.readLater=!b.readLater;await putOne('books',b);render();toast(b.readLater?'Agregado a Leer después':'Quitado de Leer después')}break;case'change-goal':await changeGoal();break;case'save-tags':if(b){b.tags=[...new Set(($('#book-tags')?.value||'').split(',').map(x=>x.trim().slice(0,36)).filter(Boolean))].slice(0,25);await putOne('books',b);render();toast('Etiquetas guardadas')}break;case'save-target':if(b){b.targetDate=$('#reading-deadline')?.value||'';await putOne('books',b);render();toast('Fecha objetivo actualizada')}break;case'bookmark':await createBookmark();break;case'go-bookmark':await goBookmark(id);break;case'delete-bookmark':await deleteBookmark(id);break;case'export-markdown':exportMarkdown();break;case'import-backup':$('#backup-input').click();break;case'relink-file':await relinkFile(id);break;case'clear-search':state.query='';render();break;case'close-detail':state.detail=null;render();break;case'read':if(id)await startReader(id);break;case'favorite':if(b){b.favorite=!b.favorite;await putOne('books',b);render()}break;case'edit-book':await editBook(id);break;case'finish':if(b){b.progress=b.progress>=100?0:100;b.status=b.progress>=100?'finished':'unread';await putOne('books',b);render()}break;case'delete-book':await deleteBook(id);break;case'new-note':await addAnnotation('note',true,id);break;case'edit-annotation':await editAnnotation(id);break;case'delete-annotation':await deleteAnnotation(id);break;case'jump':await jumpToAnnotation(id);break;case'export':exportData();break;case'reset':await resetData();break;case'close-reader':await closeReader();break;case'prev':await nextPage(-1);break;case'next':await nextPage(1);break;case'zoom-in':state.pdfScale=Math.min(3,state.pdfScale+.2);await renderPdfPage();break;case'zoom-out':state.pdfScale=Math.max(.5,state.pdfScale-.2);await renderPdfPage();break;case'rotate':state.pdfRotation=(state.pdfRotation+90)%360;await renderPdfPage();break;case'font-up':state.settings.fontSize=Math.min(26,state.settings.fontSize+2);await savePrefs();if(state.reader?.format==='DEMO')showDemoPage(state.demoPage);else applyEpubTheme();break;case'font-down':state.settings.fontSize=Math.max(14,state.settings.fontSize-2);await savePrefs();if(state.reader?.format==='DEMO')showDemoPage(state.demoPage);else applyEpubTheme();break;case'toggle-side':state.readerSide=state.readerSide?'':'reading';refreshReaderSide();break;case'reader-note':await addAnnotation('note',false);break;case'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#reader').requestFullscreen()}catch{toast('Pantalla completa no disponible')}break;case'speak':await startSpeech();break;case'tts-toggle':toggleSpeech();break;case'tts-prev':skipPhrase(-1);break;case'tts-next':skipPhrase(1);break;case'tts-stop':stopSpeech();break;case'tts-sleep':setSleep();break;case'reader-theme':{const options=['light','sepia','dark'];state.settings.readerTheme=options[(options.indexOf(state.settings.readerTheme)+1)%3];await savePrefs();$('#reader').dataset.theme=state.settings.readerTheme;applyEpubTheme();break}case'selection-copy':try{await navigator.clipboard.writeText(state.selectedText);toast('Texto copiado')}catch{toast('No se pudo copiar. Seleccioná y copiá manualmente.')}dismissSelection();break;case'selection-highlight':await addAnnotation('highlight');break;case'selection-fragment':await addAnnotation('fragment');break;case'selection-note':await addAnnotation('note');break;case'selection-speak':await startSpeech();dismissSelection();break}}
let dragDepth=0,idleTimer=null;
function resetIdle(){const overlay=$('#idle-cover');overlay?.remove();clearTimeout(idleTimer);if(state.reader&&Number(state.settings.smartTimeout)>0)idleTimer=setTimeout(()=>{if(!state.reader)return;const el=document.createElement('div');el.id='idle-cover';el.className='idle-cover';el.innerHTML='<div>'+ico('moon')+'<h2>Tu lectura te espera</h2><p>Tocá la pantalla para continuar</p></div>';el.addEventListener('click',resetIdle);$('#reader').appendChild(el)},Number(state.settings.smartTimeout)*60000)}
function wireEvents(){document.addEventListener('click',async e=>{const paletteItem=e.target.closest('[data-palette-go]');if(paletteItem){const kind=paletteItem.dataset.paletteKind,value=paletteItem.dataset.paletteGo;state.palette=false;state.paletteQuery='';if(kind==='nav'){state.view=value;state.detail=null;render()}else if(kind==='book'){state.detail=value;render()}else{render();await act(value)}return}if(e.target.id==='palette-overlay'){state.palette=false;render();return}const nav=e.target.closest('[data-nav]');if(nav){state.view=nav.dataset.nav;state.detail=null;state.query=state.view==='library'?state.query:'';render();return}const btn=e.target.closest('[data-action]');if(btn){e.stopPropagation();resetIdle();try{await act(btn.dataset.action,btn.dataset.id)}catch(err){console.error(err);toast('No pudimos completar la acción: '+(err.message||'error inesperado'))}return}const book=e.target.closest('[data-book]');if(book){state.detail=book.dataset.book;render();return}const filter=e.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;render();return}const study=e.target.closest('[data-study]');if(study){state.studyFilter=study.dataset.study;render();return}const layout=e.target.closest('[data-layout]');if(layout){state.settings.grid=layout.dataset.layout==='grid';await savePrefs();render();return}const side=e.target.closest('[data-side]');if(side){state.readerSide=side.dataset.side;refreshReaderSide();return}const toggle=e.target.closest('[data-toggle]');if(toggle){const key=toggle.dataset.toggle;state.settings[key]=!state.settings[key];await savePrefs();if(key==='keepAwake'&&state.reader){if(state.settings[key])requestWakeLock();else if(state.wakeLock)await state.wakeLock.release()}render();return}if(e.target.id==='detail-scrim'){state.detail=null;render()}});
document.addEventListener('change',async e=>{if(e.target.id==='backup-input'){await importBackup(e.target.files?.[0]);e.target.value='';return}if(e.target.id==='relink-input'){await saveRelinkedFile(e.target.files?.[0],e.target.dataset.id);e.target.value='';return}if(e.target.dataset.bookCollection!==undefined){const b=bookBy(e.target.dataset.bookCollection);if(b){b.collections=e.target.value?[e.target.value]:[];await putOne('books',b);toast('Colección asignada')}return}if(e.target.id==='collection-filter'){state.collectionFilter=e.target.value;render();return}if(e.target.id==='tag-filter'){state.tagFilter=e.target.value;render();return}if(e.target.id==='file-input'){await importFiles(e.target.files);e.target.value='';return}if(e.target.id==='format-filter'){state.type=e.target.value;render();return}if(e.target.id==='sort-books'){state.settings.sort=e.target.value;await savePrefs();render();return}const key=e.target.dataset.setting;if(key){state.settings[key]=['fontSize','lineHeight','voiceSpeed','smartTimeout','goalMinutes'].includes(key)?Number(e.target.value):e.target.value;await savePrefs();if(state.reader){if(key==='readerTheme'){$('#reader').dataset.theme=state.settings.readerTheme;applyEpubTheme()}if(['fontSize','lineHeight'].includes(key)){applyEpubTheme();if(state.reader.format==='DEMO')showDemoPage(state.demoPage)}if(key==='voiceSpeed'&&state.speaking)speakPhrase();resetIdle()}else render()}});
document.addEventListener('input',e=>{if(e.target.id==='palette-search'){state.paletteQuery=e.target.value;const pos=e.target.selectionStart;render();const f=$('#palette-search');f?.setSelectionRange(pos,pos);return}if(e.target.id==='library-search'){state.query=e.target.value;const pos=e.target.selectionStart;render();const f=$('#library-search');f?.focus();f?.setSelectionRange(pos,pos);return}if(e.target.id==='study-search'){state.studyQuery=e.target.value;const pos=e.target.selectionStart;render();const f=$('#study-search');f?.focus();f?.setSelectionRange(pos,pos);return}if(e.target.id==='global-search'){state.query=e.target.value;if(state.view!=='library')state.view='library';const pos=e.target.selectionStart;render();const inp=$('#global-search');inp.focus();try{inp.setSelectionRange(pos,pos)}catch{}}});
document.addEventListener('keydown',async e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();state.palette=!state.palette;state.paletteQuery='';render();return}if(state.palette){if(e.key==='Escape'){state.palette=false;render()}if(e.key==='Enter'){e.preventDefault();$('#palette-overlay [data-palette-go]')?.click()}return}if(e.target.closest('input,textarea,select,[contenteditable]'))return;if(!state.reader){if((e.key==='Enter'||e.key===' ')&&e.target.dataset.book){e.preventDefault();state.detail=e.target.dataset.book;render()}if(e.key==='Escape'&&state.detail){state.detail=null;render()}return}resetIdle();if(e.key==='ArrowRight'){e.preventDefault();await nextPage(1)}if(e.key==='ArrowLeft'){e.preventDefault();await nextPage(-1)}if(e.key===' '){e.preventDefault();toggleSpeech()}if(e.key.toLowerCase()==='f'&&!e.ctrlKey&&!e.metaKey)act('fullscreen');if(e.key.toLowerCase()==='n'&&!e.ctrlKey&&!e.metaKey)act('reader-note');if(e.key==='Escape'&&state.readerSide){state.readerSide='';refreshReaderSide()}});
document.addEventListener('mouseup',e=>{if(!state.reader||state.reader.format!=='PDF'||!e.target.closest('#pdf-stage'))return;const txt=window.getSelection()?.toString().trim();if(txt){state.selectedText=txt;state.selectedPos=state.page;showSelectionMenu()}});
document.addEventListener('touchend',e=>{if(!state.reader||state.reader.format!=='PDF')return;setTimeout(()=>{const txt=window.getSelection()?.toString().trim();if(txt&&$('#pdf-stage')?.contains(window.getSelection()?.anchorNode)){state.selectedText=txt;state.selectedPos=state.page;showSelectionMenu()}},150)});
document.addEventListener('pointerdown',()=>{if(state.reader)resetIdle()},{passive:true});
document.addEventListener('dragenter',e=>{if(!Array.from(e.dataTransfer?.types||[]).includes('Files'))return;e.preventDefault();dragDepth++;$('#drop-overlay').classList.remove('hidden')});document.addEventListener('dragover',e=>{if(Array.from(e.dataTransfer?.types||[]).includes('Files'))e.preventDefault()});document.addEventListener('dragleave',e=>{if(!Array.from(e.dataTransfer?.types||[]).includes('Files'))return;dragDepth=Math.max(0,dragDepth-1);if(!dragDepth)$('#drop-overlay').classList.add('hidden')});document.addEventListener('drop',async e=>{e.preventDefault();dragDepth=0;$('#drop-overlay').classList.add('hidden');if(e.dataTransfer?.files?.length)await importFiles(e.dataTransfer.files)});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.reader&&state.settings.keepAwake)requestWakeLock()});window.addEventListener('beforeunload',()=>{if(state.reader){state.reader.time=(state.reader.time||0)+Math.round((Date.now()-state.sessionStart)/1000);putOne('books',state.reader)}})}
async function init(){try{db=await openDB();const [books,annotations,sessions,prefs,collectionsPref]=await Promise.all([getAll('books'),getAll('annotations'),getAll('sessions'),getOne('prefs','settings'),getOne('prefs','collections')]);state.books=books;state.annotations=annotations;state.sessions=sessions;state.settings={...defaultSettings,...(prefs||{})};state.collections=Array.isArray(collectionsPref?.items)?collectionsPref.items:[];if(!state.books.length){state.books=[{...sampleBook}];await putOne('books',state.books[0])}wireEvents();render();if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(e=>console.info('Sin PWA offline:',e))}catch(e){console.error(e);$('#app').innerHTML='<main class="boot"><div class="boot-icon">M<span>.</span></div><h2>No se pudo abrir la biblioteca local</h2><p>Probá otro navegador o habilitá el almacenamiento del sitio.</p></main>'}}
init();

